import React from "react";
import {
  AbsoluteFill,
  Img,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { BRAND, BRAND_FONT_FACE_CSS } from "remotion/theme";
import { springIn, ambientDrift } from "remotion/motion";

export const fps = 25;
export const durationInFrames = 815;

const C = BRAND.colors;

// Strippable preview backdrop. On a transparent (ProRes/qtrle) export the
// render queue replaces <Background /> with nothing, leaving a clean alpha
// overlay you drop on top of the real talking-head footage.
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backdrops/talking-head-c2094.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ---- helpers -----------------------------------------------------------

// 0->1 envelope for a beat window: ramps in over `fin` frames, holds, ramps
// out over `fout`. Never fades the scene to black — content recedes to
// transparent while the next beat / the corner bug takes over.
function beatEnv(
  frame: number,
  start: number,
  end: number,
  fin = 10,
  fout = 12,
): number {
  const i = interpolate(frame, [start, start + fin], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const o = interpolate(frame, [end - fout, end], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return Math.min(i, o);
}

// Beat windows (frames @ 25fps). See the script timestamps.
const A = { start: 0, end: 86 }; // 48 locations / the bleed
const B = { start: 92, end: 208 }; // reports & dashboards miss it
const Cb = { start: 210, end: 322 }; // Apify -> Zapier -> Power BI pipeline
const D = { start: 324, end: 538 }; // manual, one zip / one day
const E = { start: 540, end: 600 }; // a system that runs itself
const F = { start: 602, end: 778 }; // weekly refresh + surface, then recede
const BUG_IN = 748; // corner bug appears as the panel parks

export default function LocationsOverlay() {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Right-anchored panel geometry.
  const panelW = width * 0.33;
  const pad = base * 0.03;
  const bodyH = base * 0.46;

  // Panel entrance + park. It holds present, then recedes (scale + drift +
  // fade to TRANSPARENT, never black) as the corner bug takes over near the end.
  const panelIn = springIn(frame, vfps, 0, "LIQUID");
  const park = interpolate(frame, [BUG_IN - 18, BUG_IN + 14], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const parkE = park * park * (3 - 2 * park); // smoothstep
  const panelOpacity = (0.0 + panelIn) * (1 - parkE);
  const panelScale =
    interpolate(panelIn, [0, 1], [0.96, 1]) * (1 - parkE * 0.06);
  const panelDriftX = interpolate(panelIn, [0, 1], [base * 0.03, 0]);
  const panelDriftY =
    ambientDrift(frame, base * 0.004, 90, "panel") + parkE * -base * 0.02;

  // header label per beat
  const label =
    frame < B.start
      ? "48 LOCATIONS"
      : frame < Cb.start
        ? "WHAT REPORTS SEE"
        : frame < D.start
          ? "THE PIPELINE"
          : frame < E.start
            ? "MANUAL TODAY"
            : frame < F.start
              ? "RUNS ITSELF"
              : "WEEKLY · AUTOMATIC";

  return (
    <>
      <style>{BRAND_FONT_FACE_CSS}</style>
      <AbsoluteFill style={{ background: "transparent" }}>
        <Background />

        {/* ---- right-anchored morphing panel ---- */}
        <div
          style={{
            position: "absolute",
            right: base * 0.05,
            top: "50%",
            width: panelW,
            padding: pad,
            background: C.card,
            border: `1px solid ${C.border}`,
            borderRadius: base * 0.02,
            boxShadow: "0 24px 64px rgba(0,0,0,0.45)",
            display: "flex",
            flexDirection: "column",
            gap: pad * 0.9,
            opacity: panelOpacity,
            transform: `translateY(-50%) translate(${panelDriftX}px, ${panelDriftY}px) scale(${panelScale})`,
            transformOrigin: "right center",
          }}
        >
          {/* header */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: base * 0.012,
            }}
          >
            <div
              style={{
                width: base * 0.012,
                height: base * 0.012,
                borderRadius: "50%",
                background: C.orange,
                boxShadow: `0 0 ${base * 0.012}px ${C.orange}`,
              }}
            />
            <div
              style={{
                fontFamily: BRAND.fonts.primary,
                fontWeight: 600,
                fontSize: base * 0.018,
                letterSpacing: "0.12em",
                color: C.textMuted,
              }}
            >
              {label}
            </div>
          </div>

          <div style={{ width: "100%", height: 1, background: C.border }} />

          {/* body — beats crossfade in the same area */}
          <div style={{ position: "relative", height: bodyH }}>
            <BeatLocations frame={frame} fps={vfps} base={base} win={A} />
            <BeatReports frame={frame} fps={vfps} base={base} win={B} />
            <BeatPipeline frame={frame} fps={vfps} base={base} win={Cb} />
            <BeatManual frame={frame} fps={vfps} base={base} win={D} />
            <BeatRunsItself frame={frame} fps={vfps} base={base} win={E} />
            <BeatWeekly frame={frame} fps={vfps} base={base} win={F} />
          </div>
        </div>

        {/* ---- corner bug: the resting state ("stays out of your way") ---- */}
        <CornerBug frame={frame} fps={vfps} base={base} />
      </AbsoluteFill>
    </>
  );
}

// =======================================================================
// BEAT A — 48 dots fill in; one flares orange on "bleeding"; down-sparkline
// =======================================================================
function BeatLocations({ frame, fps, base, win }: any) {
  const op = beatEnv(frame, win.start, win.end);
  if (op <= 0) return null;
  const lf = Math.max(0, frame - win.start);

  const cols = 6;
  const rows = 8;
  const dot = base * 0.018;
  const gap = base * 0.02;
  const badIndex = 27;
  const flare = springIn(lf, fps, 47, "ELASTIC"); // lands on "bleeding"

  return (
    <Layer op={op}>
      <div style={{ display: "flex", flexDirection: "column", gap: base * 0.02 }}>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${cols}, ${dot}px)`,
            gap,
            justifyContent: "center",
          }}
        >
          {Array.from({ length: cols * rows }).map((_, i) => {
            const reveal = springIn(lf, fps, 4 + i * 1.1, "SNAPPY");
            const isBad = i === badIndex;
            const pulse = isBad
              ? 1 + Math.max(0, Math.sin((lf - 47) / 4)) * 0.25 * flare
              : 1;
            return (
              <div
                key={i}
                style={{
                  width: dot,
                  height: dot,
                  borderRadius: "50%",
                  background: isBad
                    ? `rgba(248,102,6,${flare})`
                    : C.textSubtle,
                  opacity: isBad ? reveal : reveal * 0.55,
                  transform: `scale(${reveal * pulse})`,
                  boxShadow: isBad
                    ? `0 0 ${base * 0.02 * flare}px ${C.orange}`
                    : "none",
                }}
              />
            );
          })}
        </div>

        {/* down sparkline — appears with the flare */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: base * 0.01,
            opacity: flare,
            transform: `translateY(${interpolate(flare, [0, 1], [base * 0.01, 0])}px)`,
          }}
        >
          <svg
            width={base * 0.11}
            height={base * 0.045}
            viewBox="0 0 110 45"
            style={{ overflow: "visible" }}
          >
            <polyline
              points="0,6 22,12 44,16 66,28 88,36 110,42"
              fill="none"
              stroke={C.orange}
              strokeWidth={3}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={260}
              strokeDashoffset={interpolate(flare, [0, 1], [260, 0])}
            />
          </svg>
          <div
            style={{
              fontFamily: BRAND.fonts.primary,
              fontWeight: 700,
              fontSize: base * 0.022,
              color: C.orange,
            }}
          >
            ▼ 3 wks
          </div>
        </div>
      </div>
    </Layer>
  );
}

// =======================================================================
// BEAT B — flat report rows; the bad location hidden inside the average
// =======================================================================
function BeatReports({ frame, fps, base, win }: any) {
  const op = beatEnv(frame, win.start, win.end);
  if (op <= 0) return null;
  const lf = Math.max(0, frame - win.start);

  const rowGap = base * 0.022;
  const barH = base * 0.03;
  const rows = ["Brand report", "Platform dashboard"];
  // a faint marker that the bad location is absorbed into the average
  const sink = interpolate(lf, [40, 80], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <Layer op={op}>
      <div style={{ display: "flex", flexDirection: "column", gap: rowGap, width: "100%" }}>
        {rows.map((r, ri) => {
          const reveal = springIn(lf, fps, 6 + ri * 14, "SNAPPY");
          return (
            <div key={ri} style={{ opacity: reveal }}>
              <div
                style={{
                  fontFamily: BRAND.fonts.primary,
                  fontWeight: 600,
                  fontSize: base * 0.02,
                  color: C.textMuted,
                  marginBottom: base * 0.008,
                }}
              >
                {r}
              </div>
              {/* flat, "all-level" track */}
              <div
                style={{
                  position: "relative",
                  width: "100%",
                  height: barH,
                  borderRadius: barH / 2,
                  background: "rgba(255,255,255,0.08)",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    width: `${interpolate(reveal, [0, 1], [0, 92])}%`,
                    background: C.textSubtle,
                    opacity: 0.5,
                  }}
                />
                {/* the one bad location, briefly visible, then sinks into the average */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    bottom: 0,
                    left: `${62 + ri * 6}%`,
                    width: base * 0.006,
                    background: C.orange,
                    opacity: sink * reveal,
                    boxShadow: `0 0 ${base * 0.01}px ${C.orange}`,
                  }}
                />
              </div>
            </div>
          );
        })}
        <div
          style={{
            fontFamily: BRAND.fonts.primary,
            fontWeight: 600,
            fontSize: base * 0.019,
            color: C.textSubtle,
            marginTop: base * 0.006,
            opacity: springIn(lf, fps, 34, "GENTLE"),
          }}
        >
          averaged away
        </div>
      </div>
    </Layer>
  );
}

// =======================================================================
// BEAT C (HERO) — Apify -> Zapier -> Power BI with a flow pulse + ~15 min
// =======================================================================
function BeatPipeline({ frame, fps, base, win }: any) {
  const op = beatEnv(frame, win.start, win.end);
  if (op <= 0) return null;
  const lf = Math.max(0, frame - win.start);

  const node = base * 0.085;
  const n1 = springIn(lf, fps, 6, "SNAPPY");
  const n2 = springIn(lf, fps, 22, "SNAPPY");
  const n3 = springIn(lf, fps, 38, "SNAPPY");
  const lineP = springIn(lf, fps, 30, "LIQUID");
  // flow pulse travels the row, repeating
  const travel = (lf % 45) / 45;
  const chip = springIn(lf, fps, 61, "ELASTIC"); // "~15 min" near 11s

  const NodeShell = ({ scale, children, name }: any) => (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: base * 0.01 }}>
      <div
        style={{
          width: node,
          height: node,
          borderRadius: base * 0.016,
          background: C.card,
          border: `2px solid ${C.orange}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${scale})`,
          opacity: scale,
          boxShadow: `0 0 ${base * 0.018}px rgba(248,102,6,0.35)`,
        }}
      >
        {children}
      </div>
      <div
        style={{
          fontFamily: BRAND.fonts.primary,
          fontWeight: 600,
          fontSize: base * 0.017,
          color: C.text,
          opacity: scale,
        }}
      >
        {name}
      </div>
    </div>
  );

  return (
    <Layer op={op}>
      <div
        style={{
          position: "relative",
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: base * 0.04,
        }}
      >
        <div
          style={{
            position: "relative",
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
          }}
        >
          {/* connector line behind the nodes */}
          <div
            style={{
              position: "absolute",
              top: node / 2,
              left: "14%",
              right: "14%",
              height: 2,
              background: C.border,
              transform: `scaleX(${lineP})`,
              transformOrigin: "left center",
            }}
          />
          {/* flow pulse */}
          <div
            style={{
              position: "absolute",
              top: node / 2 - base * 0.006,
              left: `${interpolate(travel, [0, 1], [14, 86])}%`,
              width: base * 0.012,
              height: base * 0.012,
              borderRadius: "50%",
              background: C.orange,
              boxShadow: `0 0 ${base * 0.016}px ${C.orange}`,
              opacity: lineP,
            }}
          />

          <NodeShell scale={n1} name="Apify">
            <Img
              src={staticFile("assets/apify/Apify symbol colors.svg")}
              style={{ width: node * 0.5, height: "auto" }}
            />
          </NodeShell>
          <NodeShell scale={n2} name="Zapier">
            {/* lightning glyph */}
            <svg width={node * 0.42} height={node * 0.42} viewBox="0 0 24 24">
              <path d="M13 2 L4 14 H11 L10 22 L20 9 H13 Z" fill={C.orange} />
            </svg>
          </NodeShell>
          <NodeShell scale={n3} name="Power BI">
            {/* mini bar chart */}
            <div style={{ display: "flex", alignItems: "flex-end", gap: node * 0.06, height: node * 0.42 }}>
              {[0.5, 0.75, 1].map((h, i) => (
                <div
                  key={i}
                  style={{
                    width: node * 0.1,
                    height: `${h * 100}%`,
                    background: C.orange,
                    borderRadius: 2,
                  }}
                />
              ))}
            </div>
          </NodeShell>
        </div>

        {/* ~15 min chip */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: base * 0.01,
            padding: `${base * 0.012}px ${base * 0.022}px`,
            borderRadius: 999,
            background: C.card,
            border: `1.5px solid ${C.orange}`,
            opacity: chip,
            transform: `scale(${interpolate(chip, [0, 1], [0.8, 1])})`,
          }}
        >
          <div
            style={{
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 700,
              fontSize: base * 0.03,
              color: C.text,
            }}
          >
            ~15 min
          </div>
        </div>
      </div>
    </Layer>
  );
}

// =======================================================================
// BEAT D — manual cursor ticks row by row, collapses to "1 zip / 1 day"
// =======================================================================
function BeatManual({ frame, fps, base, win }: any) {
  const op = beatEnv(frame, win.start, win.end);
  if (op <= 0) return null;
  const lf = Math.max(0, frame - win.start);

  // D1: ticking rows (0..~150). D2: collapse to single dot (~150..end)
  const collapse = interpolate(lf, [150, 185], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const collapseE = collapse * collapse * (3 - 2 * collapse);

  const rowCount = 5;
  const rowH = base * 0.05;
  const active = Math.floor(lf / 20) % rowCount;

  return (
    <Layer op={op}>
      {/* ticking list */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: 1 - collapseE,
          transform: `scale(${interpolate(collapseE, [0, 1], [1, 0.96])})`,
          display: "flex",
          flexDirection: "column",
          gap: base * 0.012,
        }}
      >
        {Array.from({ length: rowCount }).map((_, i) => {
          const reveal = springIn(lf, fps, 6 + i * 8, "SNAPPY");
          const isActive = i === active;
          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: base * 0.014,
                height: rowH,
                padding: `0 ${base * 0.014}px`,
                borderRadius: base * 0.008,
                background: isActive ? "rgba(248,102,6,0.16)" : "rgba(255,255,255,0.05)",
                border: `1px solid ${isActive ? C.orange : "transparent"}`,
                opacity: reveal,
              }}
            >
              <div
                style={{
                  width: base * 0.012,
                  height: base * 0.012,
                  borderRadius: "50%",
                  background: isActive ? C.orange : C.textSubtle,
                }}
              />
              <div
                style={{
                  flex: 1,
                  height: base * 0.008,
                  borderRadius: 4,
                  background: "rgba(255,255,255,0.12)",
                }}
              />
              {/* tiny cursor */}
              {isActive && (
                <div
                  style={{
                    fontFamily: BRAND.fonts.primary,
                    fontSize: base * 0.02,
                    color: C.text,
                  }}
                >
                  ▸
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* collapsed: a single map dot = one zip, one day */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: base * 0.02,
          opacity: collapseE,
          transform: `scale(${interpolate(collapseE, [0, 1], [0.9, 1])})`,
        }}
      >
        <div
          style={{
            position: "relative",
            width: base * 0.05,
            height: base * 0.05,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: "50%",
              border: `2px solid ${C.orange}`,
              opacity: 0.4,
              transform: `scale(${1 + Math.max(0, Math.sin(lf / 6)) * 0.5})`,
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: "30%",
              borderRadius: "50%",
              background: C.orange,
              boxShadow: `0 0 ${base * 0.02}px ${C.orange}`,
            }}
          />
        </div>
        <div
          style={{
            fontFamily: BRAND.fonts.primary,
            fontWeight: 700,
            fontSize: base * 0.024,
            color: C.text,
          }}
        >
          1 zip · 1 day
        </div>
      </div>
    </Layer>
  );
}

// =======================================================================
// BEAT E — auto-refresh loop glyph spins up ("a system that runs itself")
// =======================================================================
function BeatRunsItself({ frame, fps, base, win }: any) {
  const op = beatEnv(frame, win.start, win.end);
  if (op <= 0) return null;
  const lf = Math.max(0, frame - win.start);
  const spin = lf * 7; // deg
  const grow = springIn(lf, fps, 4, "LIQUID");
  const r = base * 0.055;

  return (
    <Layer op={op}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: base * 0.022,
        }}
      >
        <svg
          width={r * 2}
          height={r * 2}
          viewBox="0 0 100 100"
          style={{ transform: `rotate(${spin}deg) scale(${grow})`, opacity: grow }}
        >
          <circle
            cx="50"
            cy="50"
            r="38"
            fill="none"
            stroke={C.orange}
            strokeWidth="7"
            strokeLinecap="round"
            strokeDasharray="180 60"
          />
          <path d="M50 6 L66 22 L50 22 Z" fill={C.orange} />
        </svg>
        <div
          style={{
            fontFamily: BRAND.fonts.primary,
            fontWeight: 600,
            fontSize: base * 0.022,
            color: C.textMuted,
            opacity: springIn(lf, fps, 16, "GENTLE"),
          }}
        >
          automatic
        </div>
      </div>
    </Layer>
  );
}

// =======================================================================
// BEAT F — grid returns, weekly sweep, ~3 dots surface in orange
// =======================================================================
function BeatWeekly({ frame, fps, base, win }: any) {
  const op = beatEnv(frame, win.start, win.end, 12, 30);
  if (op <= 0) return null;
  const lf = Math.max(0, frame - win.start);

  const cols = 6;
  const rows = 8;
  const dot = base * 0.018;
  const gap = base * 0.02;
  const surfaced = [12, 27, 40];
  const surface = springIn(lf, fps, 60, "ELASTIC");
  // weekly sweep — a soft highlight band travelling down the grid
  const sweep = (lf % 60) / 60;

  return (
    <Layer op={op}>
      <div style={{ display: "flex", flexDirection: "column", gap: base * 0.02, alignItems: "center" }}>
        {/* weekly badge */}
        <div
          style={{
            alignSelf: "flex-start",
            display: "flex",
            alignItems: "center",
            gap: base * 0.008,
            padding: `${base * 0.008}px ${base * 0.016}px`,
            borderRadius: 999,
            background: "rgba(248,102,6,0.16)",
            border: `1px solid ${C.orange}`,
            opacity: springIn(lf, fps, 6, "SNAPPY"),
          }}
        >
          <div
            style={{
              fontFamily: BRAND.fonts.primary,
              fontWeight: 700,
              fontSize: base * 0.016,
              letterSpacing: "0.08em",
              color: C.orange,
            }}
          >
            ↻ WEEKLY
          </div>
        </div>

        <div
          style={{
            position: "relative",
            display: "grid",
            gridTemplateColumns: `repeat(${cols}, ${dot}px)`,
            gap,
            justifyContent: "center",
            overflow: "hidden",
            padding: base * 0.004,
          }}
        >
          {Array.from({ length: cols * rows }).map((_, i) => {
            const reveal = springIn(lf, fps, 6 + i * 0.8, "SNAPPY");
            const isUp = surfaced.indexOf(i) !== -1;
            const rowFrac = Math.floor(i / cols) / rows;
            const near = 1 - Math.min(1, Math.abs(rowFrac - sweep) * 6);
            return (
              <div
                key={i}
                style={{
                  width: dot,
                  height: dot,
                  borderRadius: "50%",
                  background: isUp ? `rgba(248,102,6,${surface})` : C.textSubtle,
                  opacity: isUp ? reveal : reveal * (0.45 + near * 0.4),
                  transform: `scale(${reveal * (isUp ? 1 + surface * 0.35 : 1)}) translateY(${isUp ? -surface * base * 0.006 : 0}px)`,
                  boxShadow: isUp ? `0 0 ${base * 0.016 * surface}px ${C.orange}` : "none",
                }}
              />
            );
          })}
        </div>

        <div
          style={{
            fontFamily: BRAND.fonts.primary,
            fontWeight: 600,
            fontSize: base * 0.02,
            color: C.textMuted,
            opacity: surface,
          }}
        >
          surfaced for you
        </div>
      </div>
    </Layer>
  );
}

// =======================================================================
// Corner bug — the resting state. Slides in as the panel parks and HOLDS to
// the final frame (no fade-to-black; something is always present).
// =======================================================================
function CornerBug({ frame, fps, base }: any) {
  const inProg = springIn(Math.max(0, frame - BUG_IN), fps, 0, "LIQUID");
  if (inProg <= 0) return null;
  const breathe = 1 + ambientDrift(frame, 0.012, 80, "bug");
  const x = interpolate(inProg, [0, 1], [base * 0.04, 0]);

  return (
    <div
      style={{
        position: "absolute",
        right: base * 0.05,
        bottom: base * 0.06,
        display: "flex",
        alignItems: "center",
        gap: base * 0.014,
        padding: `${base * 0.014}px ${base * 0.02}px`,
        background: C.card,
        border: `1px solid ${C.border}`,
        borderRadius: base * 0.012,
        opacity: inProg,
        transform: `translateX(${x}px) scale(${breathe})`,
        transformOrigin: "right bottom",
      }}
    >
      <Img
        src={staticFile("assets/apify/Apify symbol colors.svg")}
        style={{ width: base * 0.04, height: "auto" }}
      />
      <div style={{ width: 1, height: base * 0.04, background: C.border }} />
      <div
        style={{
          fontFamily: BRAND.fonts.primary,
          fontWeight: 600,
          fontSize: base * 0.022,
          color: C.text,
          letterSpacing: "0.02em",
        }}
      >
        apify.com
      </div>
    </div>
  );
}

// small wrapper that crossfades a beat layer in the shared body area
function Layer({ op, children }: any) {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        opacity: op,
        transform: `translateY(${interpolate(op, [0, 1], [12, 0])}px)`,
      }}
    >
      {children}
    </div>
  );
}
